function b64Encode(str){return btoa(unescape(encodeURIComponent(str)));}function b64Decode(str){return decodeURIComponent(escape(atob(str)));} function executeBase64(){const raw = document.getElementById("b64-input").value;const decode = document.querySelector('input[name="b64-mode"]:checked').value === "decode";const out = document.getElementById("b64-result");if (!raw){GAMA.say("idle");out.textContent = "";return;}try{out.textContent = decode ? b64Decode(raw) : b64Encode(raw);GAMA.say("success");}catch (e){GAMA.say("error");out.textContent = decode ? "// not valid base64" : "// encoding failed";}}const executeBase64Debounced = GAMA.debounce(executeBase64, 300);